// lifo4_fcov: functional coverage model for the lifo4 stack block.
// Built from the approved requirement matrix (traceability_matrix.md,
// plan-audit stage). Bins are planned from the matrix scenarios, not from the RTL.
//
// CLOSURE STATEMENT
// Planned bins (15). Each bin is sampled at a rising edge of clk on the
// pre-edge port values. Crosses and occupancies require rst_n high.
//   bin  0  LIFO-PUSH        push alone, stack empty          (count == 0)
//   bin  1  LIFO-PUSH        push alone, neither empty nor full (1..3)
//   bin  2  LIFO-OVERFLOW    push alone, stack full           (count == 4)
//   bin  3  LIFO-UNDERFLOW   pop alone,  stack empty
//   bin  4  LIFO-POP         pop alone,  neither empty nor full
//   bin  5  LIFO-POP         pop alone,  stack full
//   bin  6  LIFO-BOTH-EMPTY  push and pop together, stack empty
//   bin  7  LIFO-REPLACE     push and pop together, neither empty nor full
//   bin  8  LIFO-REPLACE     push and pop together, stack full
//   bin  9  (all)            occupancy 0
//   bin 10  (all)            occupancy 1
//   bin 11  (all)            occupancy 2
//   bin 12  (all)            occupancy 3
//   bin 13  (all)            occupancy 4
//   bin 14  LIFO-RESET       rst_n low at an edge while the stack holds a word (count != 0)
// Exclusions: none. The matrix waives no scenario and names none as unreachable.
// Hit flags are not cleared by rst_n: reset is itself a scenario.

/* verilator lint_off UNUSED */
module lifo4_fcov (
    input  logic       clk, rst_n, push, pop,
    input  logic [7:0] din, dout,
    input  logic [2:0] count,
    input  logic       empty, full, err,
    output int         planned,   // how many bins the model plans
    output int         holes      // how many of them have not been hit yet
);
/* verilator lint_on UNUSED */

    localparam int NBINS = 15;

    logic [NBINS-1:0] hit = '0;

    // Occupancy class: 0 empty, 1 neither empty nor full, 2 full, 3 none (illegal count).
    function automatic int occ_class(input logic [2:0] c);
        if (c == 3'd0)      return 0;
        else if (c <= 3'd3) return 1;
        else if (c == 3'd4) return 2;
        else                return 3;
    endfunction

    // Operation: 0 push alone, 1 pop alone, 2 both, 3 idle.
    function automatic int op_class(input logic pu, input logic po);
        if (pu && !po)      return 0;
        else if (!pu && po) return 1;
        else if (pu && po)  return 2;
        else                return 3;
    endfunction

    always @(posedge clk) begin
        int oc;
        int op;
        oc = occ_class(count);
        op = op_class(push, pop);
        if (rst_n) begin
            if (op != 3 && oc != 3)
                hit[op*3 + oc] <= 1'b1;
            if (count <= 3'd4)
                hit[9 + int'(count)] <= 1'b1;
        end else begin
            if (count != 3'd0)
                hit[14] <= 1'b1;
        end
    end

    assign planned = NBINS;
    assign holes   = NBINS - $countones(hit);

endmodule
